{"command":"cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"

	"golang.org/x/image/bmp"
)

func main() {
	image.RegisterFormat("bmp", "BM", bmp.Decode, bmp.DecodeConfig)
	var tr, tc, s, d int
	var m string
	var nobg, credits, goOut, version bool
	flag.IntVar(&tr, "tr", 0, "")
	flag.IntVar(&tc, "tc", 0, "")
	flag.IntVar(&s, "s", 0, "")
	flag.IntVar(&d, "d", 0, "")
	flag.StringVar(&m, "m", "000000", "")
	flag.BoolVar(&nobg, "nobg", false, "")
	flag.BoolVar(&credits, "credits", false, "")
	flag.BoolVar(&goOut, "go", false, "")
	flag.BoolVar(&version, "version", false, "")
	flag.Parse()

	if version {
		fmt.Println("1.3.2")
		return
	}
	if credits {
		fmt.Println("Credits...")
		return
	}

	args := flag.Args()
	if len(args) < 1 {
		fmt.Println("Usage...")
		return
	}

	file, err := os.Open(args[0])
	if err != nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	img, _, err := image.Decode(file)
	if err != nil {
		fmt.Println(err)
		return
	}

	termW := tc
	if termW == 0 {
		termW = 80
	}
	termH := tr
	if termH == 0 {
		termH = 22 // piping default
	}

	// Resize logic based on -s
	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()

	var newW, newH int

	if s == 0 { // Resize
		newW = termW
		newH = termH * 2
	} else if s == 1 { // Fill
		newW = termW
		newH = termH * 2
	} else if s == 2 { // Fit
		maxW := termW
		maxH := (termH + 1) * 2
		scaleW := float64(maxW) / float64(imgW)
		scaleH := float64(maxH) / float64(imgH)
		scale := math.Min(scaleW, scaleH)
		newW = int(math.Round(float64(imgW) * scale))
		newH = int(math.Round(float64(imgH) * scale))
		newH -= 2
		if newH < 0 {
			newH = 0
		}
	}

	if newW == 0 || newH == 0 {
		return
	}

	// scale image using nearest neighbor or bilinear
	// for simplicity, nearest neighbor to get pixels
	scaled := image.NewRGBA(image.Rect(0, 0, newW, newH))
	for y := 0; y < newH; y++ {
		for x := 0; x < newW; x++ {
			srcX := int(float64(x)*float64(imgW)/float64(newW))
			srcY := int(float64(y)*float64(imgH)/float64(newH))
			if srcX >= imgW { srcX = imgW - 1 }
			if srcY >= imgH { srcY = imgH - 1 }
			scaled.Set(x, y, img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY))
		}
	}

	// render half-blocks
	if d == 0 {
		for y := 0; y < newH; y += 2 {
			for x := 0; x < newW; x++ {
				c1 := scaled.RGBAAt(x, y)
				var c2 color.RGBA
				if y+1 < newH {
					c2 = scaled.RGBAAt(x, y+1)
				}
				// Foreground is top pixel, Background is bottom pixel
				// Char is upper half block ▀? No, it's lower half block ▄
				// If lower half block, Foreground is BOTTOM, Background is TOP
				bg := c1 // TOP
				fg := c2 // BOTTOM
				fmt.Printf("\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm▄", bg.R, bg.G, bg.B, fg.R, fg.G, fg.B)
			}
			fmt.Printf("\033[0m\n")
		}
	}
}
EOF
go run main.go -tr 2 -tc 2 test_4x2.bmp
