{"command":"cat <<'EOF' > bmp.go
package main

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"io"
)

func decodeBMP(r io.Reader) (image.Image, error) {
	var header struct {
		Magic [2]byte
		Size  uint32
		Rsvd  uint32
		Off   uint32
	}
	if err := binary.Read(r, binary.LittleEndian, &header); err != nil {
		return nil, err
	}
	if header.Magic[0] != 'B' || header.Magic[1] != 'M' {
		return nil, fmt.Errorf("not a BMP")
	}

	var info struct {
		Size   uint32
		Width  int32
		Height int32
		Planes uint16
		Bpp    uint16
		Comp   uint32
		ImgSz  uint32
		XRes   int32
		YRes   int32
		Clr    uint32
		ImpClr uint32
	}
	if err := binary.Read(r, binary.LittleEndian, &info); err != nil {
		return nil, err
	}

	if info.Bpp != 24 && info.Bpp != 32 {
		return nil, fmt.Errorf("only 24bpp or 32bpp BMP supported")
	}
	if info.Comp != 0 {
		return nil, fmt.Errorf("compressed BMP not supported")
	}

	w := int(info.Width)
	h := int(info.Height)
	if h < 0 {
		h = -h
	}

	bpp := int(info.Bpp) / 8
	rowSize := (w*bpp + 3) &^ 3

	img := image.NewRGBA(image.Rect(0, 0, w, h))
	row := make([]byte, rowSize)

	for y := h - 1; y >= 0; y-- {
		if _, err := io.ReadFull(r, row); err != nil {
			return nil, err
		}
		for x := 0; x < w; x++ {
			b := row[x*bpp]
			g := row[x*bpp+1]
			rd := row[x*bpp+2]
			a := uint8(255)
			if bpp == 4 {
				a = row[x*bpp+3]
			}
			img.Set(x, y, color.RGBA{rd, g, b, a})
		}
	}
	return img, nil
}
EOF
cat <<'EOF' > main.go
package main

import (
	"flag"
	"fmt"
	"image"
	"image/color"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strings"
	"strconv"
)

var d1Chars = []rune{' ', '░', '▒', '▓', '█'}
var d2Chars = []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}

func max(a, b uint8) uint8 {
	if a > b {
		return a
	}
	return b
}
func max3(a, b, c uint8) uint8 {
	return max(a, max(b, c))
}

func main() {
	var tr, tc, s, d int
	var m string
	var nobg, credits, goOut, version bool
	flag.IntVar(&tr, "tr", 0, "")
	flag.IntVar(&tc, "tc", 0, "")
	flag.IntVar(&s, "s", 0, "")
	flag.IntVar(&d, "d", 0, "")
	flag.StringVar(&m, "m", "000000", "")
	flag.BoolVar(&nobg, "nobg", false, "")
	flag.BoolVar(&credits, "credits", false, "")
	flag.BoolVar(&goOut, "go", false, "")
	flag.BoolVar(&version, "version", false, "")
	flag.Parse()

	if version {
		fmt.Println("   ___  _____  ____\n  / _ \\/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau\n / ___// /_>  </ __/ -_) __/  ' \\ https://github.com/eliukblau/pixterm\n/_/  /___/_/|_|\\__/\\__/_/ /_/_/_/                1.3.2\n")
		return
	}
	if credits {
		fmt.Println("CONTRIBUTORS...")
		return
	}

	args := flag.Args()
	if len(args) < 1 {
		fmt.Println("USAGE:\n\n  executable [options] image/url\n")
		return
	}

	file, err := os.Open(args[0])
	if err != nil {
		fmt.Println(err)
		return
	}
	defer file.Close()

	img, _, err := image.Decode(file)
	if err != nil {
		file.Seek(0, 0)
		img, err = decodeBMP(file)
		if err != nil {
			fmt.Println("decode error:", err)
			return
		}
	}

	termW := tc
	termH := tr
	if termW == 0 {
		termW = 80
	}
	if termH == 0 {
		termH = 22 // pip default
	}

	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()
	if imgW == 0 || imgH == 0 {
		return
	}

	var newW, newH int

	if s == 0 { // Resize
		newW = termW
		newH = termH * 2
	} else if s == 1 { // Fill
		maxW := termW
		maxH := termH * 2
		scaleW := float64(maxW) / float64(imgW)
		scaleH := float64(maxH) / float64(imgH)
		scale := math.Max(scaleW, scaleH)
		newW = int(math.Round(float64(imgW) * scale))
		newH = int(math.Round(float64(imgH) * scale))
	} else if s == 2 { // Fit
		maxW := termW
		maxH := (termH + 1) * 2
		scaleW := float64(maxW) / float64(imgW)
		scaleH := float64(maxH) / float64(imgH)
		scale := math.Min(scaleW, scaleH)
		newW = int(math.Round(float64(imgW) * scale))
		newH = int(math.Round(float64(imgH) * scale))
		newH -= 2
		if newH < 0 {
			newH = 0
		}
	}

	if newW <= 0 || newH <= 0 {
		return
	}

	scaled := image.NewRGBA(image.Rect(0, 0, newW, newH))
	for y := 0; y < newH; y++ {
		for x := 0; x < newW; x++ {
			srcX := int(float64(x)*float64(imgW)/float64(newW))
			srcY := int(float64(y)*float64(imgH)/float64(newH))
			if srcX >= imgW { srcX = imgW - 1 }
			if srcY >= imgH { srcY = imgH - 1 }
			scaled.Set(x, y, img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY))
		}
	}

	// bg color
	bgR, bgG, bgB := 0, 0, 0
	if len(m) == 6 {
		val, _ := strconv.ParseUint(m, 16, 32)
		bgR = int((val >> 16) & 0xFF)
		bgG = int((val >> 8) & 0xFF)
		bgB = int(val & 0xFF)
	}

	for y := 0; y < newH; y += 2 {
		for x := 0; x < newW; x++ {
			c1 := scaled.RGBAAt(x, y)
			c2 := color.RGBA{0, 0, 0, 255}
			if y+1 < newH {
				c2 = scaled.RGBAAt(x, y+1)
			}

			if d == 0 {
				fmt.Printf("\033[48;2;%d;%d;%dm\033[38;2;%d;%d;%dm▄", c1.R, c1.G, c1.B, c2.R, c2.G, c2.B)
			} else {
				// average top and bottom pixel for FG
