	_ "image/jpeg"
	_ "image/png"
	"math"
	"os"
	"strconv"
)

var d1Chars = []rune{' ', '░', '▒', '▓', '█'}
var d2Chars = []rune{' ', '.', ':', ';', '+', '=', 'x', 'X', '$', '&', '#'}

func max(a, b uint8) uint8 {
	if a > b { return a }
	return b
}
func max3(a, b, c uint8) uint8 {
	return max(a, max(b, c))
}

func getPixel(img image.Image, x, y int) (r, g, b, a uint32) {
	bounds := img.Bounds()
	if x < 0 { x = 0 }
	if y < 0 { y = 0 }
	if x >= bounds.Dx() { x = bounds.Dx() - 1 }
	if y >= bounds.Dy() { y = bounds.Dy() - 1 }
	return img.At(bounds.Min.X+x, bounds.Min.Y+y).RGBA()
}

func scaleBilinear(img image.Image, newW, newH int) *image.RGBA {
	bounds := img.Bounds()
	imgW := bounds.Dx()
	imgH := bounds.Dy()
	scaled := image.NewRGBA(image.Rect(0, 0, newW, newH))
	if newW == 0 || newH == 0 {
		return scaled
	}
	ratioX := float64(imgW-1) / float64(newW)
	if newW == 1 { ratioX = 0 }
	ratioY := float64(imgH-1) / float64(newH)
	if newH == 1 { ratioY = 0 }

	for y := 0; y < newH; y++ {
		yy := float64(y) * ratioY
		yInt := int(math.Floor(yy))
		yDiff := yy - float64(yInt)

		for x := 0; x < newW; x++ {
			xx := float64(x) * ratioX
			xInt := int(math.Floor(xx))
			xDiff := xx - float64(xInt)

			r1, g1, b1, a1 := getPixel(img, xInt, yInt)
			r2, g2, b2, a2 := getPixel(img, xInt+1, yInt)
			r3, g3, b3, a3 := getPixel(img, xInt, yInt+1)
			r4, g4, b4, a4 := getPixel(img, xInt+1, yInt+1)

			interp := func(v1, v2, v3, v4 uint32) uint8 {
				f1, f2, f3, f4 := float64(v1>>8), float64(v2>>8), float64(v3>>8), float64(v4>>8)
				top := f1*(1-xDiff) + f2*xDiff
				bot := f3*(1-xDiff) + f4*xDiff
				val := top*(1-yDiff) + bot*yDiff
				if val < 0 { val = 0 }
				if val > 255 { val = 255 }
				return uint8(val)
			}

			r := interp(r1, r2, r3, r4)
			g := interp(g1, g2, g3, g4)
			b := interp(b1, b2, b3, b4)
			a := interp(a1, a2, a3, a4)

